CREATE INDEX audit_time ON audit_events(occurred_at);
CREATE INDEX outbox_delivery ON change_outbox(delivered_at,change_id);
CREATE UNIQUE INDEX execution_idempotency ON executions(client_id,tool_id,idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'Audit is append-only'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit_events WHEN coalesce((SELECT audit_retention_authorized FROM bridge_config WHERE singleton_id=1),0)<>1 BEGIN SELECT RAISE(ABORT,'Audit retention uses a separately authorized maintenance transaction'); END;
-- Additive executable design/reference storage. No real clients or devices.
CREATE TABLE device_view_scopes(scope_id TEXT NOT NULL PRIMARY KEY CHECK(length(scope_id)=64 AND scope_id NOT GLOB '*[^0-9a-f]*'),profile_id TEXT NOT NULL REFERENCES connection_profiles,target_key TEXT NOT NULL,android_user_id INTEGER NOT NULL CHECK(android_user_id>=0),backend_instance_id TEXT NOT NULL,device_instance_id TEXT NOT NULL,UNIQUE(profile_id,target_key,android_user_id,backend_instance_id,device_instance_id));
CREATE TRIGGER device_scope_target BEFORE INSERT ON device_view_scopes WHEN NOT EXISTS(SELECT 1 FROM connection_profiles p WHERE p.profile_id=new.profile_id AND p.android_user_id=new.android_user_id) OR (new.target_key<>'platform:local' AND NOT EXISTS(SELECT 1 FROM target_app_profiles t WHERE t.target_id=new.target_key AND t.connection_profile_id=new.profile_id)) BEGIN SELECT RAISE(ABORT,'Unknown device scope or Android user'); END;
CREATE TRIGGER device_scope_immutable BEFORE UPDATE ON device_view_scopes BEGIN SELECT RAISE(ABORT,'Device scope identity is immutable'); END;
CREATE TABLE device_view_invalidations(scope_id TEXT NOT NULL REFERENCES device_view_scopes,capability_epoch INTEGER NOT NULL CHECK(capability_epoch BETWEEN 0 AND 9007199254740991),reason TEXT NOT NULL CHECK(length(reason)>0),occurred_at TEXT NOT NULL,PRIMARY KEY(scope_id,capability_epoch));
CREATE TRIGGER invalidation_no_update BEFORE UPDATE ON device_view_invalidations BEGIN SELECT RAISE(ABORT,'Invalidation evidence is append-only'); END;
CREATE TRIGGER invalidation_no_delete BEFORE DELETE ON device_view_invalidations BEGIN SELECT RAISE(ABORT,'Invalidation evidence is append-only'); END;
CREATE TABLE device_capability_facts(facts_id TEXT NOT NULL PRIMARY KEY CHECK(length(facts_id)=64 AND facts_id NOT GLOB '*[^0-9a-f]*'),scope_id TEXT NOT NULL REFERENCES device_view_scopes,capability_epoch INTEGER NOT NULL,observed_at TEXT NOT NULL,document_json TEXT NOT NULL CHECK(json_valid(document_json) AND json_type(document_json)='object'),UNIQUE(facts_id,scope_id,capability_epoch),FOREIGN KEY(scope_id,capability_epoch) REFERENCES device_view_invalidations);
CREATE TRIGGER capability_facts_no_update BEFORE UPDATE ON device_capability_facts BEGIN SELECT RAISE(ABORT,'Captured facts are immutable'); END;
CREATE TABLE device_views(view_id TEXT NOT NULL PRIMARY KEY CHECK(length(view_id)=64 AND view_id NOT GLOB '*[^0-9a-f]*'),scope_id TEXT NOT NULL REFERENCES device_view_scopes,registry_id TEXT NOT NULL,catalog_generation INTEGER NOT NULL CHECK(catalog_generation>=1),overlay_generation INTEGER NOT NULL CHECK(overlay_generation>=0),capability_epoch INTEGER NOT NULL CHECK(capability_epoch>=0),view_generation INTEGER NOT NULL CHECK(view_generation>=1),inventory_count INTEGER NOT NULL CHECK(inventory_count>=0),facts_id TEXT NOT NULL,document_json TEXT NOT NULL CHECK(json_valid(document_json)),state TEXT NOT NULL CHECK(state IN ('staged','sealed')),UNIQUE(view_id,scope_id),FOREIGN KEY(facts_id,scope_id,capability_epoch) REFERENCES device_capability_facts(facts_id,scope_id,capability_epoch));
CREATE TABLE device_view_entries(view_id TEXT NOT NULL REFERENCES device_views ON DELETE CASCADE,entry_id TEXT NOT NULL CHECK(length(entry_id)=64 AND entry_id NOT GLOB '*[^0-9a-f]*'),entity_kind TEXT NOT NULL CHECK(entity_kind IN ('binding','type','other')),state TEXT NOT NULL CHECK(state IN ('available','unavailable','unknown')),reason_codes_json TEXT NOT NULL CHECK(json_valid(reason_codes_json) AND json_type(reason_codes_json)='array' AND json_array_length(reason_codes_json)>0),schema_hash TEXT CHECK(schema_hash IS NULL OR length(schema_hash)=64 AND schema_hash NOT GLOB '*[^0-9a-f]*'),dependencies_json TEXT NOT NULL CHECK(json_valid(dependencies_json) AND json_type(dependencies_json)='array'),graph_digest TEXT CHECK(graph_digest IS NULL OR length(graph_digest)=64 AND graph_digest NOT GLOB '*[^0-9a-f]*'),document_json TEXT NOT NULL CHECK(json_valid(document_json)),PRIMARY KEY(view_id,entry_id),CHECK(state<>'available' OR (schema_hash IS NOT NULL AND graph_digest IS NOT NULL)));
CREATE TABLE device_view_active(scope_id TEXT NOT NULL PRIMARY KEY REFERENCES device_view_scopes,view_id TEXT,registry_id TEXT NOT NULL,catalog_generation INTEGER NOT NULL CHECK(catalog_generation>=1),overlay_generation INTEGER NOT NULL CHECK(overlay_generation>=0),capability_epoch INTEGER NOT NULL CHECK(capability_epoch BETWEEN 0 AND 9007199254740991),generation INTEGER NOT NULL CHECK(generation BETWEEN 0 AND 9007199254740991),stale INTEGER NOT NULL CHECK(stale IN (0,1)),expected_inventory_count INTEGER NOT NULL CHECK(expected_inventory_count>=0),FOREIGN KEY(view_id,scope_id) REFERENCES device_views(view_id,scope_id),FOREIGN KEY(scope_id,capability_epoch) REFERENCES device_view_invalidations DEFERRABLE INITIALLY DEFERRED);
CREATE TRIGGER device_active_bootstrap BEFORE INSERT ON device_view_active WHEN new.view_id IS NOT NULL OR new.generation<>0 OR new.capability_epoch<>0 OR new.stale<>1 BEGIN SELECT RAISE(ABORT,'Device scope begins with stale generation zero'); END;
CREATE TRIGGER device_active_no_delete BEFORE DELETE ON device_view_active BEGIN SELECT RAISE(ABORT,'Invalidate device scope rather than deleting pointer'); END;
CREATE TRIGGER device_active_update BEFORE UPDATE ON device_view_active WHEN new.scope_id<>old.scope_id OR new.catalog_generation<old.catalog_generation OR new.overlay_generation<old.overlay_generation OR
 (new.stale=1 AND (new.capability_epoch<>old.capability_epoch+1 OR new.generation<>old.generation OR new.view_id IS NOT old.view_id OR (new.expected_inventory_count<>old.expected_inventory_count AND new.registry_id=old.registry_id AND new.catalog_generation=old.catalog_generation AND new.overlay_generation=old.overlay_generation))) OR
 (new.stale=0 AND (new.capability_epoch<>old.capability_epoch OR new.generation<>old.generation+1 OR new.registry_id<>old.registry_id OR new.catalog_generation<>old.catalog_generation OR new.overlay_generation<>old.overlay_generation OR NOT EXISTS(SELECT 1 FROM device_views v WHERE v.view_id=new.view_id AND v.scope_id=new.scope_id AND v.state='sealed' AND v.capability_epoch=new.capability_epoch AND v.view_generation=new.generation AND v.registry_id=new.registry_id AND v.catalog_generation=new.catalog_generation AND v.overlay_generation=new.overlay_generation AND v.inventory_count=new.expected_inventory_count) OR new.expected_inventory_count<>old.expected_inventory_count))
 BEGIN SELECT RAISE(ABORT,'Device view CAS, scope, epoch or catalog pin mismatch'); END;
CREATE TRIGGER device_entries_staged BEFORE INSERT ON device_view_entries WHEN (SELECT state FROM device_views WHERE view_id=new.view_id) IS NOT 'staged' BEGIN SELECT RAISE(ABORT,'Device membership is sealed'); END;
CREATE TRIGGER device_entries_no_update BEFORE UPDATE ON device_view_entries BEGIN SELECT RAISE(ABORT,'Device view entries are immutable'); END;
CREATE TRIGGER device_view_seal BEFORE UPDATE ON device_views WHEN old.state<>'staged' OR new.state<>'sealed' OR new.view_id<>old.view_id OR new.scope_id<>old.scope_id OR new.registry_id<>old.registry_id OR new.catalog_generation<>old.catalog_generation OR new.overlay_generation<>old.overlay_generation OR new.capability_epoch<>old.capability_epoch OR new.view_generation<>old.view_generation OR new.facts_id<>old.facts_id OR new.inventory_count<>old.inventory_count OR new.document_json<>old.document_json OR new.inventory_count<>(SELECT count(*) FROM device_view_entries WHERE view_id=new.view_id) OR EXISTS(SELECT 1 FROM device_view_entries e,json_each(e.dependencies_json) d WHERE e.view_id=new.view_id AND e.state='available' AND NOT EXISTS(SELECT 1 FROM device_view_entries t WHERE t.view_id=e.view_id AND t.entry_id=json_extract(d.value,'$.entry_id') AND t.entity_kind='type' AND t.state='available' AND t.schema_hash=json_extract(d.value,'$.schema_hash'))) BEGIN SELECT RAISE(ABORT,'Immutable device view or incoherent complete type graph'); END;
CREATE TABLE device_view_pins(pin_id TEXT PRIMARY KEY,view_id TEXT NOT NULL REFERENCES device_views,purpose TEXT NOT NULL CHECK(purpose IN ('execution','cursor')),expires_at TEXT NOT NULL);
CREATE TABLE device_view_gc(singleton INTEGER PRIMARY KEY CHECK(singleton=1),authorized INTEGER NOT NULL DEFAULT 0 CHECK(authorized IN (0,1)));
INSERT INTO device_view_gc VALUES(1,0);
CREATE TRIGGER device_view_delete_guard BEFORE DELETE ON device_views WHEN EXISTS(SELECT 1 FROM device_view_active WHERE view_id=old.view_id) OR EXISTS(SELECT 1 FROM device_view_pins WHERE view_id=old.view_id) OR (old.state='sealed' AND (SELECT authorized FROM device_view_gc WHERE singleton=1) IS NOT 1) BEGIN SELECT RAISE(ABORT,'Active or pinned device view cannot be collected'); END;
CREATE TRIGGER device_entries_delete_guard BEFORE DELETE ON device_view_entries WHEN EXISTS(SELECT 1 FROM device_view_active WHERE view_id=old.view_id) OR EXISTS(SELECT 1 FROM device_view_pins WHERE view_id=old.view_id) OR ((SELECT state FROM device_views WHERE view_id=old.view_id)='sealed' AND (SELECT authorized FROM device_view_gc WHERE singleton=1) IS NOT 1) BEGIN SELECT RAISE(ABORT,'Sealed active or pinned membership cannot be deleted'); END;
CREATE TRIGGER capability_facts_delete_guard BEFORE DELETE ON device_capability_facts WHEN (SELECT authorized FROM device_view_gc WHERE singleton=1) IS NOT 1 BEGIN SELECT RAISE(ABORT,'Fact retention requires explicit maintenance transaction'); END;
CREATE VIEW resolved_device_catalog AS SELECT s.scope_id,s.profile_id,s.target_key,a.view_id,a.capability_epoch,a.generation,e.entry_id,e.entity_kind,e.state,e.reason_codes_json,e.schema_hash,e.dependencies_json,e.graph_digest FROM device_view_active a JOIN device_view_scopes s USING(scope_id) JOIN device_view_entries e USING(view_id) WHERE a.stale=0;
CREATE VIEW binding_availability AS SELECT entry_id AS binding_id,target_key,state,json_extract(reason_codes_json,'$[0]') AS reason_code,scope_id,profile_id,view_id,capability_epoch,generation,schema_hash,graph_digest,reason_codes_json FROM resolved_device_catalog WHERE entity_kind='binding';
CREATE TABLE binding_wire_contracts(contract_id TEXT NOT NULL PRIMARY KEY CHECK(length(contract_id)=64 AND contract_id NOT GLOB '*[^0-9a-f]*'),binding_id TEXT NOT NULL,schema_hash TEXT NOT NULL,descriptor TEXT NOT NULL,interface_version INTEGER CHECK(interface_version IS NULL OR interface_version>=0),interface_hash TEXT,transaction_code INTEGER NOT NULL CHECK(transaction_code BETWEEN 0 AND 4294967295),flags INTEGER NOT NULL CHECK(flags BETWEEN 0 AND 4294967295),oneway INTEGER NOT NULL CHECK(oneway IN (0,1)),argument_codec_json TEXT NOT NULL CHECK(json_valid(argument_codec_json)),response_codec_json TEXT NOT NULL CHECK(json_valid(response_codec_json)),proof_source_json TEXT NOT NULL CHECK(json_valid(proof_source_json) AND json_type(proof_source_json)='object'),proof_state TEXT NOT NULL CHECK(proof_state IN ('verified','unknown','unsupported')),FOREIGN KEY(binding_id,schema_hash) REFERENCES binding_mappings);
CREATE TRIGGER wire_proof_no_update BEFORE UPDATE ON binding_wire_contracts BEGIN SELECT RAISE(ABORT,'Version wire evidence rather than rewriting it'); END;
CREATE TRIGGER wire_proof_no_delete BEFORE DELETE ON binding_wire_contracts BEGIN SELECT RAISE(ABORT,'Retain wire evidence while versioned'); END;

CREATE TRIGGER device_facts_current BEFORE INSERT ON device_capability_facts WHEN NOT EXISTS(SELECT 1 FROM device_view_active a JOIN device_view_scopes s USING(scope_id) WHERE a.scope_id=new.scope_id AND a.capability_epoch=new.capability_epoch AND json_extract(new.document_json,'$.capability_epoch')=new.capability_epoch AND json_extract(new.document_json,'$.observed_at')=new.observed_at AND json_extract(new.document_json,'$.profile_id')=s.profile_id AND json_extract(new.document_json,'$.target_key')=s.target_key AND json_extract(new.document_json,'$.android_user_id')=s.android_user_id AND json_extract(new.document_json,'$.backend_instance_id')=s.backend_instance_id AND json_extract(new.document_json,'$.device_instance_id')=s.device_instance_id) BEGIN SELECT RAISE(ABORT,'Captured facts scope or epoch mismatch'); END;
CREATE TRIGGER device_view_stage BEFORE INSERT ON device_views WHEN new.state<>'staged' OR NOT EXISTS(SELECT 1 FROM device_view_active a WHERE a.scope_id=new.scope_id AND new.capability_epoch=a.capability_epoch AND new.view_generation=a.generation+1 AND new.registry_id=a.registry_id AND new.catalog_generation=a.catalog_generation AND new.overlay_generation=a.overlay_generation AND new.inventory_count=a.expected_inventory_count) BEGIN SELECT RAISE(ABORT,'Stage must pin the complete current inventory and epoch'); END;
CREATE TRIGGER device_entry_document_consistent BEFORE INSERT ON device_view_entries WHEN json_extract(new.document_json,'$.entry_id') IS NOT new.entry_id OR json_extract(new.document_json,'$.entity_kind') IS NOT new.entity_kind OR json_extract(new.document_json,'$.state') IS NOT new.state OR json_type(new.document_json,'$.schema_hash') IS NULL OR json_extract(new.document_json,'$.schema_hash') IS NOT new.schema_hash OR json_type(new.document_json,'$.graph_digest') IS NULL OR json_extract(new.document_json,'$.graph_digest') IS NOT new.graph_digest OR json(json_extract(new.document_json,'$.reason_codes')) IS NOT json(new.reason_codes_json) OR json(json_extract(new.document_json,'$.dependencies')) IS NOT json(new.dependencies_json) OR EXISTS(SELECT 1 FROM json_each(new.reason_codes_json) WHERE type<>'text' OR length(value)=0) BEGIN SELECT RAISE(ABORT,'Device entry JSON disagrees with authoritative columns'); END;
CREATE TRIGGER device_header_document_consistent BEFORE INSERT ON device_views WHEN json_extract(new.document_json,'$.schema_version') IS NOT '2.0.0' OR json_extract(new.document_json,'$.view_id') IS NOT new.view_id OR json_extract(new.document_json,'$.facts_id') IS NOT new.facts_id OR json_extract(new.document_json,'$.registry_id') IS NOT new.registry_id OR json_extract(new.document_json,'$.catalog_generation') IS NOT new.catalog_generation OR json_extract(new.document_json,'$.overlay_generation') IS NOT new.overlay_generation OR json_extract(new.document_json,'$.capability_epoch') IS NOT new.capability_epoch OR json_extract(new.document_json,'$.view_generation') IS NOT new.view_generation OR json_extract(new.document_json,'$.inventory_count') IS NOT new.inventory_count OR json_type(new.document_json,'$.entries') IS NOT NULL BEGIN SELECT RAISE(ABORT,'Device header JSON disagrees with immutable metadata'); END;
