    "/v1/catalog/device-views/current": {
      "get": {
        "operationId": "getCurrentDeviceView",
        "description": "Read bounded current status/header and strong dv1 ETag, including generation-zero bootstrap with null header. Authorized exact profile/target only. stale forbids admission; availability is separate from permission.",
        "security": [
          {
            "catalogAuth": [
