            "schema": {
              "type": "string",
              "minLength": 1
            }
          },
          {
            "name": "target_key",
            "in": "query",
            "required": true,
            "schema": {
              "type": "string",
              "minLength": 1
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Current snapshot plus stale/capability epoch; no remote facts accepted",
